settings.cb_custom_css:
.search-button{
    display: none !important;
}
.search-box{
    border: 1px solid black !important;
}
.search-results {
    width: 100% !important;

}

@media only screen and (max-width: 767px) {
  .ttSearchInputBox {
    border:  1px solid black !important;
  }
  .search-container {
    margin-bottom: 30px !important;
    border: 1px solid black !important;
    border-radius: 5px;
  }
  .search-results {
    width: 100% !important;
  }
}

@media only screen and  (orientation: landscape) {

  .search-container {
    margin-bottom: 30px !important;   
  }

}
